#!/usr/bin/env bash
# Replay the two-block test board's project (design change C3) from a fresh `make draw` to every
# committed sheet, in a work directory, checking every sha256 and every generated op-list on the
# way. Exits non-zero on any mismatch. Test data: these pages are never sent for review.
#
# Fails loudly: the work directory must be new or empty, every command's status is checked through
# pipes (pipefail), each generated op-list must be byte-identical to the committed one, each
# `akcli draw` must report APPLIED (its dry run also exits 0 having written nothing - TOOLING.md
# step 4), and each block sheet must pass hierarchical-labels.ts's post-condition after its ops.
#
# The fixture has no boards/ directory (a perfboard.json committed in the repository would be found
# by the repo-wide declaration walk and checked as a board), so the declaration `make draw` reads
# is written into the work directory, in a directory named for the board, and `tools/cli/draw.ts`
# - the program `make draw` runs - is run from there. It writes build/draw/two-block-board inside
# the repository, as `make draw` does.
#
# usage: bash replay.sh <new-or-empty-work-dir>
set -eu
set -o pipefail
here="$(cd "$(dirname "$0")" && pwd)"
drafted="$(cd "$here/.." && pwd)"
root="$(cd "$here/../../../../.." && pwd)"
akcli="$root/draughting/venv-akcli/bin/akcli"
module="$root/tests/fixtures/two-block-board/two-block-board.ts"
board=two-block-board
DRAFT_A=3faf354d31ae7c4d005dcd4ffd51a9e585c578c85cd67215c3151c5c99dfae2b
DRAFT_B=d6806d007e635118ae5778fa498cb3a98c6789dd2b38ef9ef516f3b3a40135f0
PAGE_A=230f0598397656930d09f5e8563fdb60f1fe84476a03edcb5df1d081c6a8a235
PAGE_B=c410234cbe1bf13a22025105caafac1304b2c82d4b2df8aa3b7d14431b24f966
ROOT_BLANK=38f21c9df048d071a57a016bbaa41c839cddfbe9e46b380c40412356180f13f8
ROOT=7fb295e5b088b19991728fba4ae06934ef0856cabfc38faab0a788fa0ba49389

fail() {
  echo "replay.sh: FAILED - $1" >&2
  exit 1
}

[ "$#" -eq 1 ] || fail "expected one argument, a new or empty work directory; got $#"
mkdir -p "$1"
work="$(cd "$1" && pwd)"
[ -z "$(ls -A "$work")" ] || fail "$work is not empty; replay into a new or empty directory so nothing from an earlier run is read"
[ -x "$akcli" ] || fail "akcli not found at $akcli"
[ -f "$module" ] || fail "the fixture circuit module is not at $module"

sha() {
  shasum -a 256 "$1" | cut -d' ' -f1
}

check() {
  got="$(sha "$work/$1")" || fail "could not hash $work/$1"
  [ "$got" = "$3" ] || fail "after $2, $1 is $got, expected $3"
  echo "after $2, $1: $got"
}

same() {
  cmp -s "$work/repair/$1" "$here/$1" || fail "repair/$1 generated by this replay differs from the committed $here/$1"
  echo "generated repair/$1 matches the committed copy"
}

apply() {
  "$akcli" plan "$work/$1" --ops "$work/repair/$2" 2>/dev/null | tail -1 || fail "akcli plan $2 failed"
  log="$("$akcli" draw "$work/$1" --ops "$work/repair/$2" --apply 2>/dev/null)" || fail "akcli draw $2 --apply failed"
  echo "$log" | tail -1
  echo "$log" | grep -q 'status: APPLIED' || fail "akcli draw $2 did not report APPLIED - nothing was written"
}

# 1. make draw: one draft per block, each intent checked against the committed copy.
mkdir -p "$work/$board" "$work/repair/a" "$work/repair/b" "$work/repair/root"
printf '{"kind":"pcb","circuit":"%s","export":"twoBlockBoard"}\n' "$module" > "$work/$board/perfboard.json"
(cd "$work/$board" && bun "$root/tools/cli/draw.ts") > "$work/make-draw.log" 2>&1 \
  || fail "tools/cli/draw.ts failed; see $work/make-draw.log"
grep -q '^NO INDEPENDENT NETLIST:' "$work/make-draw.log" || fail "make draw printed no NO INDEPENDENT NETLIST block"
for b in a b; do
  cp "$root/build/draw/$board/$b/$b.kicad_sch" "$work/$b.kicad_sch" || fail "make draw wrote no sheet for block $b"
  cmp -s "$root/build/draw/$board/$b.intent.json" "$here/$b/intent.json" \
    || fail "the intent make draw generated for block $b differs from the committed $b/intent.json - the model has changed since this repair"
  echo "the intent make draw generated for block $b matches the committed copy"
done
check a.kicad_sch "make draw" "$DRAFT_A"
check b.kicad_sch "make draw" "$DRAFT_B"

# 2. Each block: copperhead's labels on port nets become one hierarchical label per port; a global
#    label on a private net becomes local.
for b in a b; do
  bun "$root/tools/draught/hierarchical-labels.ts" ops "$module" "$b" "$work/$b.kicad_sch" \
    > "$work/repair/$b/01-hierarchical-labels.json" || fail "hierarchical-labels.ts ops $b failed"
  same "$b/01-hierarchical-labels.json"
  apply "$b.kicad_sch" "$b/01-hierarchical-labels.json"
  bun "$root/tools/draught/hierarchical-labels.ts" check "$module" "$b" "$work/$b.kicad_sch" \
    || fail "block $b fails the hierarchical-label post-condition after its op-list"
done
check a.kicad_sch "01-hierarchical-labels" "$PAGE_A"
check b.kicad_sch "01-hierarchical-labels" "$PAGE_B"

# 3. The root: its starting text, then one sheet per block, each pin wired to its parent net.
bun "$root/tools/draught/assemble-root.ts" blank "$board" > "$work/$board.kicad_sch" || fail "assemble-root.ts blank failed"
check "$board.kicad_sch" "assemble-root blank" "$ROOT_BLANK"
bun "$root/tools/draught/assemble-root.ts" ops "$module" twoBlockBoard "$board" > "$work/repair/root/01-assemble.json" \
  || fail "assemble-root.ts ops failed"
same root/01-assemble.json
apply "$board.kicad_sch" root/01-assemble.json
check "$board.kicad_sch" "root/01-assemble" "$ROOT"
check a.kicad_sch "root/01-assemble (unchanged)" "$PAGE_A"
check b.kicad_sch "root/01-assemble (unchanged)" "$PAGE_B"

# 4. Every replayed sheet is byte-identical to the committed one.
for f in "$board.kicad_sch" a.kicad_sch b.kicad_sch; do
  cmp -s "$work/$f" "$drafted/$f" || fail "the replayed $f differs from the committed $drafted/$f"
  echo "the replayed $f is byte-identical to the committed sheet"
done
